#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int main() {
    long long x;
    std::cin >> x;

    static std::vector<long long> ONES(17);
    ONES[1] = 1;
    for (int i = 2; i < 17; ++i) {
        ONES[i] = 10 * ONES[i - 1] + 1;
    }

    auto solve = [&](long long x) {
        return go(x, 16, ONES);
    };

    auto go = [&](long long x, int len, const std::vector<long long>& ONES) -> long long {
        x = std::abs(x);
        if (x % ONES[len] == 0) {
            return (x / ONES[len]) * len;
        }
        long long low = x / ONES[len];
        long long high = low + 1;

        long long ret1 = low * len + go(x - low * ONES[len], len - 1, ONES);
        long long ret2 = high * len + go(high * ONES[len] - x, len - 1, ONES);
        return std::min(ret1, ret2);
    };

    std::cout << solve(x) << std::endl;

    return 0;
}
